package com.example.media.contract.upload;

import org.jspecify.annotations.Nullable;

import java.time.Instant;
import java.util.List;
import java.util.Objects;

/**
 * The data needed to issue an upload permission.
 *
 * <p>The caller chooses the usage budget and the expiry; the registry stores them as given and the
 * application service clamps them to its configured maximums before creating the row. The token
 * itself is not here: it is generated by the caller and only its hash reaches the registry.</p>
 */
public record NewUploadPermission(
        UploadKey uploadKey,
        String extension,
        @Nullable String contentType,
        @Nullable Long maxBytes,
        List<String> eagerTransformationNames,
        @Nullable String incomingTransformationName,
        UploadVisibility visibility,
        Instant expiresAt,
        int maxUses
) {
    public NewUploadPermission {
        Objects.requireNonNull(uploadKey, "uploadKey");
        Objects.requireNonNull(extension, "extension");
        if (extension.isBlank())
            throw new IllegalArgumentException("the extension must not be blank");
        if (maxBytes != null && maxBytes <= 0)
            throw new IllegalArgumentException("maxBytes must be positive: " + maxBytes);
        Objects.requireNonNull(eagerTransformationNames, "eagerTransformationNames");
        eagerTransformationNames = List.copyOf(eagerTransformationNames);
        Objects.requireNonNull(visibility, "visibility");
        Objects.requireNonNull(expiresAt, "expiresAt");
        if (maxUses <= 0)
            throw new IllegalArgumentException("maxUses must be positive: " + maxUses);
    }
}
